class IPAddress:
    MAX_OCTET_VALUE = 255
    OCTET_COUNT = 4
    BINARY_FORMAT = '08b'

    def __init__(self, ip_address):
        self._ip_address = ip_address

    @property
    def ip_address(self):
        return self._ip_address

    @ip_address.setter
    def ip_address(self, value):
        self._ip_address = value

    def is_valid(self):
        octets = self.ip_address.split('.')
        if len(octets) != self.OCTET_COUNT:
            return False
        return self._are_octets_valid(octets)

    def _are_octets_valid(self, octets):
        for octet in octets:
            if not self._is_valid_octet(octet):
                return False
        return True

    def _is_valid_octet(self, octet):
        return octet.isdigit() and int(octet) <= self.MAX_OCTET_VALUE

    def get_octets(self):
        if not self.is_valid():
            return []
        return self.ip_address.split('.')

    def get_binary(self):
        if not self.is_valid():
            return ''
        return '.'.join(self._get_binary_octets())

    def _get_binary_octets(self):
        return [self._octet_to_binary(octet) for octet in self.get_octets()]

    def _octet_to_binary(self, octet):
        return format(int(octet), self.BINARY_FORMAT)
